const body = $json.body || $json;
const gaps = body.all_gaps || body.top_opportunities || [];
const seen = new Set();
const normalized = gaps.filter(g => {
  const key = (g.title || g.topic || '').toLowerCase().trim();
  if (!key || seen.has(key)) return false;
  seen.add(key);
  return true;
}).map((g, i) => ({
  id: 'CAND-' + Date.now() + '-' + String(i+1).padStart(3,'0'),
  title: g.title || g.topic,
  keyword: g.keyword || g.primary_keyword || '',
  practice_area: g.practice_area || 'General Law',
  target_state: g.target_state || 'Federal',
  priority: g.priority || g.priority_score || 5,
  gap_reason: g.reason || g.gap_reason || ''
}));

return normalized.map(n => ({ json: n }));

parameters.prompt:
=You are an editorial director for common-law.ai.

Score and rank this legal topic for publication priority:
Topic: "{{ $json.title }}"
Keyword: "{{ $json.keyword }}"
Practice Area: {{ $json.practice_area }}
Jurisdiction: {{ $json.jurisdiction_detail || $json.target_state }}
Search Intent: {{ $json.search_intent || 'informational' }}
Target Audience: {{ $json.target_audience || 'General public' }}
Competitor Angle: {{ $json.competitor_angle || 'Not analyzed' }}

IMPORTANT LEGAL SAFEGUARD:
Do NOT invent keyword search volume, difficulty scores, or rankings unless a real SEO provider supplied them.

Return ONLY valid JSON:
{
  "content_score": 85,
  "score_breakdown": {
    "search_demand": "high|medium|low",
    "competition": "high|medium|low",
    "commercial_value": "high|medium|low",
    "content_gap_urgency": "high|medium|low"
  },
  "recommendation": "publish|deprioritize|reject",
  "editorial_notes": "Brief rationalization for score",
  "suggested_article_type": "comprehensive guide|FAQ|state-specific guide"
}

parameters.jsCode:
const scoreRaw = $json.message?.content || $json.text || '{}';
let scoreData = {};
try {
  const c = scoreRaw.replace(/```json/g,'').replace(/```/g,'').trim();
  scoreData = JSON.parse(c);
} catch(e) {
  scoreData = { content_score: 50, recommendation: 'review', editorial_notes: 'Score parse fallback' };
}

const input = $('Normalize Topic Candidates').item.json;
const jurisRaw = $('Check Jurisdiction and Search Intent').item.json.message?.content ||
                 $('Check Jurisdiction and Search Intent').item.json.text || '{}';
let jurisData = {};
try {
  jurisData = JSON.parse(jurisRaw.replace(/```json/g,'').replace(/```/g,'').trim());
} catch(e) {}

const isValid = scoreData.recommendation !== 'reject' && (scoreData.content_score || 50) >= 50;
const ts = new Date().toISOString();

return [{
  json: {
    topic_id: input.id,
    title_idea: input.title,
    primary_keyword: input.keyword,
    practice_area: input.practice_area,
    target_state: jurisData.jurisdiction_detail || input.target_state,
    jurisdiction: jurisData.jurisdiction || 'state',
    search_intent: jurisData.search_intent || 'informational',
    content_score: scoreData.content_score || 50,
    score_breakdown: scoreData.score_breakdown || {},
    recommendation: scoreData.recommendation || 'review',
    editorial_notes: scoreData.editorial_notes || '',
    suggested_article_type: scoreData.suggested_article_type || 'comprehensive guide',
    status: isValid ? 'NEW' : 'REJECTED',
    source_type: 'wf2_research',
    relevance_score: scoreData.content_score || 50,
    notes: [input.gap_reason, scoreData.editorial_notes].filter(Boolean).join(' | '),
    created_at: ts,
    is_valid: isValid
  }
}];
